import sys


def parse(s):
    n = len(s)
    fields = []
    i = 0
    while True:
        if i < n and s[i] == '"':
            start = i
            i += 1
            buf = []
            while True:
                if i >= n:
                    return None, start + 1
                if s[i] == '"':
                    if i + 1 < n and s[i + 1] == '"':
                        buf.append('"')
                        i += 2
                        continue
                    i += 1
                    break
                buf.append(s[i])
                i += 1
            fields.append(''.join(buf))
            if i < n and s[i] != ',':
                return None, i + 1
        else:
            j = i
            while j < n and s[j] != ',':
                if s[j] == '"':
                    return None, j + 1
                j += 1
            fields.append(s[i:j])
            i = j
        if i >= n:
            return fields, 0
        i += 1
        if i >= n:
            fields.append('')
            return fields, 0


def main():
    lines = sys.stdin.read().split('\n')
    out = []
    for i in range(int(lines[0])):
        f, col = parse(lines[1 + i] if 1 + i < len(lines) else '')
        if f is None:
            out.append("ERR %d" % col)
        else:
            out.append(str(len(f)))
            out.extend('[' + x + ']' for x in f)
    print('\n'.join(out))


