#include <iostream>
#include <string>
#include <vector>
using namespace std;

static bool parseLine(const string& s, vector<string>& fields, int& col) {
    size_t n = s.size(), i = 0;
    fields.clear();
    while (true) {
        if (i < n && s[i] == '"') {
            size_t start = i;
            i++;
            string buf;
            while (true) {
                if (i >= n) { col = (int)start + 1; return false; }
                if (s[i] == '"') {
                    if (i + 1 < n && s[i + 1] == '"') { buf += '"'; i += 2; continue; }
                    i++;
                    break;
                }
                buf += s[i++];
            }
            fields.push_back(buf);
            if (i < n && s[i] != ',') { col = (int)i + 1; return false; }
        } else {
            size_t j = i;
            while (j < n && s[j] != ',') {
                if (s[j] == '"') { col = (int)j + 1; return false; }
                j++;
            }
            fields.push_back(s.substr(i, j - i));
            i = j;
        }
        if (i >= n) return true;
        i++;
        if (i >= n) { fields.push_back(""); return true; }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    string line;
    getline(cin, line);
    int q = stoi(line);
    while (q--) {
        if (!getline(cin, line)) line.clear();
        if (!line.empty() && line.back() == '\r') line.pop_back();
        vector<string> f;
        int col = 0;
        if (!parseLine(line, f, col)) { cout << "ERR " << col << '\n'; continue; }
        cout << f.size() << '\n';
        for (auto& x : f) cout << '[' << x << "]\n";
    }
    return 0;
}
